begin;
insert into public.recursos(codigo,descricao) values('reports','Relatórios e histórico de gestão');
insert into public.recursos_plano(codigo_plano,codigo_recurso,habilitado) values('intermediate','reports',true),('complete','reports',true);
alter table public.oficinas add column revisao_configuracoes integer not null default 1;
create function private.exigir_gestao(p_oficina uuid,p_recurso text) returns uuid language plpgsql security definer set search_path='' as $$declare u uuid;begin
 u:=private.require_staff(p_oficina);if not private.has_feature(p_oficina,p_recurso) or not exists(select 1 from public.membros_oficina where oficina_id=p_oficina and usuario_id=u and ativo and perfil in ('owner','manager')) then raise exception 'Disponível somente à gerência em plano habilitado.' using errcode='42501';end if;return u;end $$;
create function public.consultar_configuracoes_oficina(p_oficina uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin
 perform private.require_staff(p_oficina);if not private.has_feature(p_oficina,'customers') then raise exception 'Assinatura indisponível' using errcode='42501';end if;
 select jsonb_build_object('nome',nome,'telefone',coalesce(telefone_e164,''),'endereco',endereco,'revisao',revisao_configuracoes) into r from public.oficinas where id=p_oficina;return r;end $$;
create function public.salvar_configuracoes_oficina(p_oficina uuid,p_revisao integer,p_nome text,p_telefone text,p_endereco jsonb) returns void language plpgsql security definer set search_path='' as $$declare u uuid;w public.oficinas%rowtype;begin
 u:=private.exigir_gestao(p_oficina,'customers');select * into w from public.oficinas where id=p_oficina for update;
 if w.revisao_configuracoes is distinct from p_revisao then raise exception 'Configurações alteradas. Atualize a página antes de salvar.' using errcode='40001';end if;
 if length(trim(coalesce(p_nome,''))) not between 2 and 120 or (coalesce(p_telefone,'')<>'' and p_telefone!~'^\+[1-9][0-9]{7,14}$') or p_endereco is null or jsonb_typeof(p_endereco)<>'object' or length(p_endereco::text)>2000 then raise exception 'Confira nome, telefone e endereço.' using errcode='22023';end if;
 update public.oficinas set nome=trim(p_nome),telefone_e164=nullif(p_telefone,''),endereco=p_endereco,revisao_configuracoes=revisao_configuracoes+1 where id=p_oficina;
 insert into public.registros_auditoria(oficina_id,usuario_autor_id,tipo_autor,acao,tipo_entidade,entidade_id,correlacao_id) values(p_oficina,u,'user','configuracoes_atualizadas','oficina',p_oficina,gen_random_uuid());
end $$;
create function public.consultar_relatorios(p_oficina uuid,p_inicio date,p_fim date) returns jsonb language plpgsql security definer set search_path='' as $$
declare r jsonb;atual jsonb;anterior jsonb;inicio_ant date;fim_ant date;d1 date;d2 date;i integer;operacao jsonb;atrasados jsonb;clientes jsonb;estoque jsonb;begin
 perform private.exigir_gestao(p_oficina,'reports');
 if p_inicio is null or p_fim is null or p_inicio>p_fim or p_fim-p_inicio>366 then raise exception 'Escolha um período de até 367 dias.' using errcode='22023';end if;
 fim_ant:=p_inicio-1;inicio_ant:=p_inicio-(p_fim-p_inicio+1);
 for i in 1..2 loop
 d1:=case when i=1 then p_inicio else inicio_ant end;d2:=case when i=1 then p_fim else fim_ant end;
 select jsonb_build_object('entregues',count(*),'vendido',coalesce(sum(total_centavos),0),'ticket',coalesce(round(avg(total_centavos)),0),'prazo_medio',round(avg(extract(epoch from (entregue_em-recebido_em))/86400)::numeric,1),'no_prazo',count(*) filter(where entrega_prevista_em is not null and entregue_em<=entrega_prevista_em),'com_previsao',count(*) filter(where entrega_prevista_em is not null)) into r from public.ordens_servico where oficina_id=p_oficina and situacao='delivered' and (entregue_em at time zone 'America/Sao_Paulo')::date between d1 and d2;
 select r||jsonb_build_object('orcamentos',count(*),'enviados',count(*) filter(where situacao not in ('draft','cancelled')),'aprovados',count(*) filter(where situacao='approved'),'recusados',count(*) filter(where situacao='declined')) into r from public.orcamentos where oficina_id=p_oficina and arquivado_em is null and (criado_em at time zone 'America/Sao_Paulo')::date between d1 and d2;
 if i=1 then atual:=r;else anterior:=r;end if;end loop;
 select jsonb_build_object('ativas',count(*),'atrasadas',count(*) filter(where entrega_prevista_em<now()),'prontas',count(*) filter(where situacao='ready'),'sem_previsao',count(*) filter(where entrega_prevista_em is null),'paradas',count(*) filter(where exists(select 1 from public.paradas_ordem_servico p where p.ordem_servico_id=w.id and p.oficina_id=p_oficina and p.encerrado_em is null))) into operacao from public.ordens_servico w where oficina_id=p_oficina and situacao not in ('delivered','cancelled');
 select operacao||jsonb_build_object('aguardando_aprovacao',count(*)) into operacao from public.orcamentos where oficina_id=p_oficina and arquivado_em is null and situacao='awaiting_approval';
 select coalesce(jsonb_agg(to_jsonb(x)),'[]') into atrasados from (select w.id,w.numero,w.dados_cliente->>'nome' cliente,w.dados_veiculo->>'modelo' veiculo,w.entrega_prevista_em,w.situacao,(select string_agg(p.detalhes,'; ') from public.paradas_ordem_servico p where p.oficina_id=p_oficina and p.ordem_servico_id=w.id and p.encerrado_em is null) motivo from public.ordens_servico w where w.oficina_id=p_oficina and w.situacao not in ('delivered','cancelled') and (w.entrega_prevista_em<now() or exists(select 1 from public.paradas_ordem_servico p where p.oficina_id=p_oficina and p.ordem_servico_id=w.id and p.encerrado_em is null)) order by w.entrega_prevista_em nulls last,w.id limit 15)x;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]') into clientes from (select cliente_id,min(dados_cliente->>'nome') nome,count(*) atendimentos,sum(total_centavos)::bigint total from public.ordens_servico where oficina_id=p_oficina and situacao='delivered' and (entregue_em at time zone 'America/Sao_Paulo')::date between p_inicio and p_fim group by cliente_id order by sum(total_centavos) desc,cliente_id limit 10)x;
 select jsonb_build_object('baixo',count(*) filter(where e.saldo<=e.minimo),'sem_custo',count(*) filter(where e.custo_centavos=0),'controlados',count(*)) into estoque from public.estoque_produtos e join public.itens_catalogo c on c.oficina_id=e.oficina_id and c.id=e.item_catalogo_id where e.oficina_id=p_oficina and c.arquivado_em is null;
 return jsonb_build_object('atual',atual,'anterior',anterior,'inicio_anterior',inicio_ant,'fim_anterior',fim_ant,'operacao',operacao,'atencao',atrasados,'clientes',clientes,'estoque',estoque);end $$;
create function public.consultar_historico_gestao(p_oficina uuid,p_inicio date,p_fim date,p_tipo text default '',p_busca text default '',p_pagina integer default 0) returns jsonb language plpgsql security definer set search_path='' as $$declare itens jsonb;total bigint;begin
 perform private.exigir_gestao(p_oficina,'reports');if p_inicio is null or p_fim is null or p_inicio>p_fim or p_fim-p_inicio>366 then raise exception 'Escolha um período de até 367 dias.' using errcode='22023';end if;
 with eventos as(
 select a.id::text id,a.criado_em data,'auditoria'::text origem,a.tipo_entidade tipo,a.acao descricao,a.usuario_autor_id autor,a.entidade_id entidade,null::text numero from public.registros_auditoria a where a.oficina_id=p_oficina
 union all select h.id::text,h.ocorrido_em,'os','ordem_servico',h.descricao,h.usuario_autor_id,h.ordem_servico_id,w.numero::text from public.historico_ordem_servico h join public.ordens_servico w on w.id=h.ordem_servico_id and w.oficina_id=h.oficina_id where h.oficina_id=p_oficina
 union all select m.id::text,m.criado_em,'estoque','estoque',m.tipo||': '||c.descricao||' · '||m.motivo,m.criado_por,m.item_catalogo_id,null from public.movimentacoes_estoque m join public.itens_catalogo c on c.id=m.item_catalogo_id and c.oficina_id=m.oficina_id where m.oficina_id=p_oficina
 ),filtrados as(select * from eventos where (data at time zone 'America/Sao_Paulo')::date between p_inicio and p_fim and (p_tipo='' or tipo=p_tipo) and concat(descricao,' ',numero) ilike '%'||left(p_busca,120)||'%')
 select (select count(*) from filtrados),(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select * from filtrados order by data desc,origem,id limit 30 offset greatest(p_pagina,0)*30)x) into total,itens;
 return jsonb_build_object('itens',itens,'total',total);end $$;
do $$declare r record;begin for r in select p.oid::regprocedure assinatura,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='public' and p.proname in ('consultar_configuracoes_oficina','salvar_configuracoes_oficina','consultar_relatorios','consultar_historico_gestao')) or (n.nspname='private' and p.proname='exigir_gestao') loop execute format('revoke all on function %s from public,anon,authenticated',r.assinatura);if r.nspname='public' then execute format('grant execute on function %s to authenticated',r.assinatura);end if;end loop;end $$;
notify pgrst,'reload schema';commit;
